(() => {
 const $=id=>document.getElementById(id), form=$('blog-form'), notice=$('blog-notice');let posts=[],slugEdited=false,uploadedFile=null,previewObjectUrl=null;
 function message(text,error=false){notice.textContent=text;notice.dataset.error=String(error)}
 const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 function markdownHtml(value){return String(value).split(/\n{2,}/).map(block=>{const lines=block.trim().split('\n');const inline=text=>escape(text).replace(/\*\*([^*\n]+)\*\*/g,'<strong>$1</strong>').replace(/\*([^*\n]+)\*/g,'<em>$1</em>').replace(/\[([^\]\n]+)\]\((https?:\/\/[^\s)]+)\)/g,'<a href="$2">$1</a>');if(!lines[0])return '';if(/^### /.test(lines[0]))return '<h3>'+inline(lines.join(' ').slice(4))+'</h3>';if(/^## /.test(lines[0]))return '<h2>'+inline(lines.join(' ').slice(3))+'</h2>';if(lines.every(line=>/^[-*] /.test(line)))return '<ul>'+lines.map(line=>'<li>'+inline(line.slice(2))+'</li>').join('')+'</ul>';if(lines.every(line=>/^\d+\. /.test(line)))return '<ol>'+lines.map(line=>'<li>'+inline(line.replace(/^\d+\. /,''))+'</li>').join('')+'</ol>';if(lines.every(line=>/^> ?/.test(line)))return '<blockquote>'+inline(lines.map(line=>line.replace(/^> ?/,'')).join(' '))+'</blockquote>';return '<p>'+lines.map(inline).join('<br>')+'</p>'}).join('')}
 function editorToMarkdown(html){const doc=new DOMParser().parseFromString(html,'text/html');const text=node=>{if(node.nodeType===Node.TEXT_NODE)return node.nodeValue;if(node.nodeType!==Node.ELEMENT_NODE)return '';const inner=Array.from(node.childNodes).map(text).join('');switch(node.tagName){case 'STRONG':case 'B':return '**'+inner+'**';case 'EM':case 'I':return '*'+inner+'*';case 'BR':return '\n';case 'A':{const href=node.getAttribute('href')||'';return /^https?:\/\/[^\s)]+$/i.test(href)?'['+inner+']('+href+')':inner}default:return inner}};return Array.from(doc.body.children).map(node=>{const inner=text(node).trim();if(!inner)return '';switch(node.tagName){case 'H2':return '## '+inner;case 'H3':return '### '+inner;case 'BLOCKQUOTE':return inner.split('\n').map(line=>'> '+line).join('\n');case 'UL':return Array.from(node.children).map(li=>'- '+text(li).trim()).join('\n');case 'OL':return Array.from(node.children).map((li,i)=>(i+1)+'. '+text(li).trim()).join('\n');default:return inner}}).filter(Boolean).join('\n\n')}
 const getEditor=()=>window.tinymce?.get('post-body');
 function setBody(value){const markdown=/<\/?(?:p|h[2-4]|ul|ol|li|strong|em|blockquote|br)\b/i.test(value)?editorToMarkdown(value):value;$('post-body').value=markdown;const editor=getEditor();if(editor)editor.setContent(markdownHtml(markdown))}
 if(window.tinymce){window.tinymce.init({selector:'#post-body',height:460,menubar:false,branding:false,plugins:'lists link',toolbar:'undo redo | blocks | bold italic | bullist numlist blockquote link',block_formats:'Paragraph=p; Heading=h2; Subheading=h3',statusbar:false,setup(editor){editor.on('init',()=>{$('fallback-toolbar').hidden=true;$('editor-hint').textContent='Format your story with the editor toolbar.';editor.setContent(markdownHtml($('post-body').value))})}})}
 async function api(options={}){const response=await window.OBI_API.fetch('/api/admin/blog',{cache:'no-store',...options});if(response.status===401){location.href='/admin/login.html';throw new Error('Please sign in as an administrator.')};const data=await response.json();if(!response.ok)throw new Error(data.error||'Could not complete the request.');return data}
 const defaultCover='/readobiism-meta.jpeg';
 $('schedule-timezone').textContent=Intl.DateTimeFormat().resolvedOptions().timeZone||'local time';
 function setPreview(url){const img=$('cover-preview');img.hidden=!url;if(url)img.src=url;else img.removeAttribute('src')}
 function localDateTime(iso){if(!iso)return '';const d=new Date(iso);if(!Number.isFinite(d.getTime()))return '';const pad=n=>String(n).padStart(2,'0');return d.getFullYear()+'-'+pad(d.getMonth()+1)+'-'+pad(d.getDate())+'T'+pad(d.getHours())+':'+pad(d.getMinutes())}
 function clearFilePreview(){if(previewObjectUrl){URL.revokeObjectURL(previewObjectUrl);previewObjectUrl=null}}
 $('post-image').addEventListener('input',()=>{clearFilePreview();setPreview($('post-image').value);$('cover-message').textContent=''});
 $('post-upload').addEventListener('change',()=>{clearFilePreview();uploadedFile=null;const file=$('post-upload').files[0];if(file){previewObjectUrl=URL.createObjectURL(file);setPreview(previewObjectUrl);$('cover-message').textContent='Selected image will be uploaded when you save.'}else{setPreview($('post-image').value);$('cover-message').textContent=''}});
 $('cover-preview').addEventListener('error',()=>{$('cover-preview').hidden=true;$('cover-message').textContent='Image preview unavailable. Check the image URL.'});
 $('admin-posts').addEventListener('error',event=>{const img=event.target;if(img.tagName==='IMG'&&!img.dataset.fallback){img.dataset.fallback='true';img.src=defaultCover}},true);
 function reset(){form.reset();clearFilePreview();uploadedFile=null;setPreview('');$('cover-message').textContent='';$('post-schedule').value='';setBody('');$('post-id').value='';$('post-author').value='OBI-ISM';$('editor-heading').textContent='New story';$('delete-post').hidden=true;$('view-post').hidden=true;$('post-slug').readOnly=false;slugEdited=false}
 function edit(p){$('post-id').value=p.id;$('post-title').value=p.title;$('post-slug').value=p.slug;$('post-slug').readOnly=Boolean(p.published_at);$('post-excerpt').value=p.excerpt;setBody(p.body);$('post-author').value=p.author;$('post-image').value=p.image_url;clearFilePreview();uploadedFile=null;$('post-upload').value='';setPreview(p.image_url);$('cover-message').textContent='';$('post-schedule').value=p.status==='scheduled'?localDateTime(p.published_at):'';$('editor-heading').textContent='Edit story';$('delete-post').hidden=false;$('view-post').hidden=p.status!=='published';$('view-post').href='/api/blog/post/'+encodeURIComponent(p.slug);slugEdited=true;window.scrollTo({top:0,behavior:'smooth'})}
 async function load(){const data=await api();posts=data.items;$('admin-posts').innerHTML=posts.map(p=>'<div class="post-row"><img src="'+escape(p.image_url||defaultCover)+'" alt=""><div class="post-row-copy"><button type="button" data-id="'+escape(p.id)+'">'+escape(p.title)+'</button><small>'+escape(p.status)+(p.status==='scheduled'?' · '+escape(new Date(p.published_at).toLocaleString()):' · '+escape(p.updated_at.slice(0,10)))+'</small></div></div>').join('')||'<p>No stories yet. Write your first story.</p>'}
 $('admin-posts').addEventListener('click',e=>{const id=e.target.closest('[data-id]')?.dataset.id;const post=posts.find(p=>p.id===id);if(post)edit(post)});
 $('new-post').onclick=reset;
 $('post-title').addEventListener('input',()=>{if(!slugEdited)$('post-slug').value=$('post-title').value.toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,120)});
 $('post-slug').addEventListener('input',()=>slugEdited=true);
 document.querySelectorAll('[data-format]').forEach(button=>button.addEventListener('click',()=>{const field=$('post-body'),start=field.selectionStart,end=field.selectionEnd,selected=field.value.slice(start,end),type=button.dataset.format;let replacement=selected;
 if(type==='bold')replacement='**'+(selected||'bold text')+'**';if(type==='italic')replacement='*'+(selected||'italic text')+'*';if(type==='heading')replacement='## '+(selected||'Heading');if(type==='quote')replacement='> '+(selected||'Quote');if(type==='list')replacement='- '+(selected||'List item');if(type==='link')replacement='['+(selected||'Link text')+'](https://example.com)';field.setRangeText(replacement,start,end,'select');field.focus()}));
 $('preview-post').addEventListener('click',()=>{const preview=$('editor-preview'),show=preview.hidden;preview.hidden=!show;$('preview-post').setAttribute('aria-expanded',String(show));if(!show)return;const inline=text=>escape(text).replace(/\*\*([^*\n]+)\*\*/g,'<strong>$1</strong>').replace(/\*([^*\n]+)\*/g,'<em>$1</em>').replace(/\[([^\]\n]+)\]\((https?:\/\/[^\s)]+)\)/g,'<a href="$2" rel="noopener noreferrer">$1</a>');preview.innerHTML=$('post-body').value.split(/\n{2,}/).map(block=>{const lines=block.trim().split('\n');if(!lines[0])return '';if(/^### /.test(lines[0]))return '<h3>'+inline(lines.join(' ').slice(4))+'</h3>';if(/^## /.test(lines[0]))return '<h2>'+inline(lines.join(' ').slice(3))+'</h2>';if(lines.every(line=>/^[-*] /.test(line)))return '<ul>'+lines.map(line=>'<li>'+inline(line.slice(2))+'</li>').join('')+'</ul>';if(lines.every(line=>/^\d+\. /.test(line)))return '<ol>'+lines.map(line=>'<li>'+inline(line.replace(/^\d+\. /,''))+'</li>').join('')+'</ol>';if(lines.every(line=>/^> ?/.test(line)))return '<blockquote>'+inline(lines.map(line=>line.replace(/^> ?/,'')).join(' '))+'</blockquote>';return '<p>'+lines.map(inline).join('<br>')+'</p>'}).join('')||'<p>Nothing to preview yet.</p>'});
 form.addEventListener('submit',async e=>{e.preventDefault();const status=e.submitter?.value||'draft',dateInput=$('post-schedule').value;let scheduled_at;
  if(status==='scheduled'){const date=new Date(dateInput);if(!dateInput||!Number.isFinite(date.getTime())||date.getTime()<=Date.now()){message('Choose a future publishing date and time.',true);return}scheduled_at=date.toISOString()}
  const buttons=form.querySelectorAll('button[type="submit"]');buttons.forEach(button=>button.disabled=true);
  try{if($('post-upload').files[0]&&uploadedFile!==$('post-upload').files[0])await uploadCover();
   const body={id:$('post-id').value,title:$('post-title').value,slug:$('post-slug').value,excerpt:$('post-excerpt').value,body:getEditor()?editorToMarkdown(getEditor().getContent()):$('post-body').value,author:$('post-author').value,image_url:$('post-image').value,status,scheduled_at};
   const result=await api({method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body)});await load();const saved=posts.find(p=>p.id===result.id);if(saved)edit(saved);message(status==='published'?'Story published.':status==='scheduled'?'Story scheduled for '+new Date(scheduled_at).toLocaleString()+'.':'Draft saved.');
  }catch(error){message(error.message,true)}finally{buttons.forEach(button=>button.disabled=false)}});
 $('delete-post').onclick=async()=>{if(!confirm('Delete this story? This cannot be undone.'))return;try{await api({method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action:'delete',id:$('post-id').value})});reset();await load();message('Story deleted.')}catch(error){message(error.message,true)}};
 async function uploadCover(){const file=$('post-upload').files[0];if(!file||!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>1048576)throw new Error('Choose a JPEG, PNG or WebP image under 1 MB.');const button=$('upload-image');button.disabled=true;try{const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('Could not read the image.'));reader.readAsDataURL(file)});const result=await api({method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action:'upload-image',data})});$('post-image').value=result.url;uploadedFile=file;clearFilePreview();setPreview(result.url);$('cover-message').textContent='Cover uploaded.'}finally{button.disabled=false}}
 $('upload-image').onclick=async()=>{try{await uploadCover();message('Cover image uploaded. Save the story to use it.')}catch(error){message(error.message,true)}};
 load().catch(e=>message(e.message,true));
})();